funcao somar_json(texto: cadeia) -> Resultado<inteiro, cadeia> {
    seja lista: vetor<inteiro> = Json.obter_lista_inteiro(texto, "valores")?;
    seja mutavel total: inteiro = 0;
    // Some os elementos de lista e retorne Resultado::Ok(total)
    retorne Resultado::Ok(total);
}

funcao inicio() {
    seja mutavel linha: cadeia = "";
    leia(linha);
    escolha somar_json(linha) {
        caso Resultado::Ok(s) => {
            escreva(s);
        }
        caso Resultado::Erro(_) => {
            escreva("invalido");
        }
    }
}
